def _add_global_secondary_index(ret, name, index_name, changes_old, changes_new, comments,
                                gsi_config, region, key, keyid, profile):
    """Updates ret iff there was a failure or in test mode."""
    if _is_in_test_mode(changes_old, changes_new):
        return
    if not _does_gsi_exist(index_name, gsi_config, changes_old, changes_new):
        ret['result'] = False
        ret['comment'] = (
            'Global secondary index {0} does not exist. '
            'Please create the index before calling this function.'.format(
                index_name))
        return

    if _gsi_has_changed(index_name, gsi_config, changes_old, changes_new):
        ret['changes'][name] = {'old': changes_old,
                                'new': changes_new}
        ret['comment'] = ('Global secondary index {0} has been updated.'
                          .format(index_name))
    else:
        ret['comment'] = ('Global secondary index {0} has not changed.'.format(
            index_name))
